import copy
import json
import math

UNKNOWN = 'UNKNOWN'
RUBRIC = ('arithmetic', 'source_fidelity', 'unknowns', 'rendered_fields', 'unsupported_claims')
CONTRACT = {'version': 1, 'max_rounds': 2, 'max_time': 3.0, 'max_cost': 4, 'rubric': list(RUBRIC)}
EVIDENCE = {
    'incident_id': 'INC-42', 'started_at': '14:05 UTC', 'deployment': '7f3a',
    'baseline_errors_per_minute': 12, 'peak_errors_per_minute': 18,
    'rollback_at': '14:17 UTC', 'observed_at': '14:22 UTC',
    'observed_errors_per_minute': 13,
    'unknown_fields': ['cause', 'affected_customer_count', 'full_recovery_time']
}
ARTIFACT_KEYS = {'incident_id','started_at','relation','deployment','baseline_errors_per_minute','peak_errors_per_minute','increase_percent','rollback_at','observed_at','observed_errors_per_minute','cause','affected_customer_count','full_recovery_time','resolved'}
FINDING_KEYS = {'id','criterion','evidence_refs','severity','correction'}
DISPOSITION_KEYS = {'finding_id','action','evidence'}
ROUND_KEYS = {'revision_id','artifact','findings','dispositions','cost','time'}
TRACE_KEYS = {'contract_version','rounds'}
CHANGE_KEYS = {'incident_id','observed_at','observed_errors_per_minute'}
VALID_REFS = {
    'arithmetic': {'baseline_errors_per_minute','peak_errors_per_minute'},
    'source_fidelity': {'incident_id','started_at','deployment','rollback_at','observed_at','observed_errors_per_minute','unknown_fields.cause'},
    'unknowns': {'unknown_fields.cause','unknown_fields.affected_customer_count','unknown_fields.full_recovery_time'},
    'rendered_fields': {'started_at','deployment','rollback_at','observed_at'},
    'unsupported_claims': {'unknown_fields.cause','unknown_fields.full_recovery_time'}
}

def exact(v, keys):
    return isinstance(v, dict) and set(v) == keys

def finite(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)

def count(v):
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0

def valid_contract():
    return (exact(CONTRACT, {'version','max_rounds','max_time','max_cost','rubric'}) and
            count(CONTRACT['version']) and CONTRACT['version'] >= 1 and
            count(CONTRACT['max_rounds']) and CONTRACT['max_rounds'] >= 1 and
            finite(CONTRACT['max_time']) and CONTRACT['max_time'] >= 0 and
            finite(CONTRACT['max_cost']) and CONTRACT['max_cost'] >= 0 and
            CONTRACT['rubric'] == list(RUBRIC))

def valid_evidence():
    keys = {'incident_id','started_at','deployment','baseline_errors_per_minute','peak_errors_per_minute','rollback_at','observed_at','observed_errors_per_minute','unknown_fields'}
    strings = ('incident_id','started_at','deployment','rollback_at','observed_at')
    nums = ('baseline_errors_per_minute','peak_errors_per_minute','observed_errors_per_minute')
    return (exact(EVIDENCE, keys) and all(isinstance(EVIDENCE[k], str) and EVIDENCE[k] for k in strings) and
            all(count(EVIDENCE[k]) for k in nums) and EVIDENCE['baseline_errors_per_minute'] > 0 and
            EVIDENCE['unknown_fields'] == ['cause','affected_customer_count','full_recovery_time'])

def good_artifact():
    return {'incident_id': EVIDENCE['incident_id'], 'started_at': EVIDENCE['started_at'], 'relation': 'after', 'deployment': EVIDENCE['deployment'], 'baseline_errors_per_minute': 12, 'peak_errors_per_minute': 18, 'increase_percent': 50, 'rollback_at': EVIDENCE['rollback_at'], 'observed_at': EVIDENCE['observed_at'], 'observed_errors_per_minute': 13, 'cause': UNKNOWN, 'affected_customer_count': UNKNOWN, 'full_recovery_time': UNKNOWN, 'resolved': UNKNOWN}

def bad_artifact():
    a = good_artifact()
    a.update({'relation': 'caused by', 'increase_percent': 40, 'cause': 'deployment 7f3a', 'affected_customer_count': 'UNSTATED', 'full_recovery_time': 'after rollback', 'resolved': True})
    return a

def valid_artifact(v):
    if not exact(v, ARTIFACT_KEYS): return False
    strings = ('incident_id','started_at','relation','deployment','rollback_at','observed_at','cause','full_recovery_time')
    if not all(isinstance(v[k], str) and v[k] for k in strings): return False
    if not all(count(v[k]) for k in ('baseline_errors_per_minute','peak_errors_per_minute','observed_errors_per_minute')): return False
    if not finite(v['increase_percent']): return False
    customer = v['affected_customer_count']
    if not (customer == UNKNOWN or count(customer) or isinstance(customer, str)): return False
    return v['resolved'] == UNKNOWN or isinstance(v['resolved'], bool)

def render(a):
    return (f"{a['started_at']}: After deployment {a['deployment']}, observed errors increased from {a['baseline_errors_per_minute']} to {a['peak_errors_per_minute']} per minute, a {a['increase_percent']:g}% increase. The team rolled back at {a['rollback_at']}; errors were {a['observed_errors_per_minute']} per minute at {a['observed_at']}. Cause, affected customer count, and full recovery time: {a['cause']}.")

def evaluate(a):
    expected = (18 - 12) / 12 * 100
    direct = (a['incident_id'] == 'INC-42' and a['started_at'] == '14:05 UTC' and a['relation'] == 'after' and a['deployment'] == '7f3a' and a['baseline_errors_per_minute'] == 12 and a['peak_errors_per_minute'] == 18 and a['rollback_at'] == '14:17 UTC' and a['observed_at'] == '14:22 UTC' and a['observed_errors_per_minute'] == 13)
    return {'arithmetic': a['increase_percent'] == expected, 'source_fidelity': direct, 'unknowns': all(a[k] == UNKNOWN for k in EVIDENCE['unknown_fields']), 'rendered_fields': render(a) == render(good_artifact()), 'unsupported_claims': a['relation'] == 'after' and a['cause'] == UNKNOWN and a['resolved'] == UNKNOWN}

def valid_finding(v):
    return (exact(v, FINDING_KEYS) and all(isinstance(v[k], str) and v[k] for k in ('id','criterion','severity','correction')) and v['severity'] in ('blocking','nonblocking') and isinstance(v['evidence_refs'], list) and all(isinstance(x, str) for x in v['evidence_refs']))

def valid_disposition(v):
    return (exact(v, DISPOSITION_KEYS) and all(isinstance(v[k], str) and v[k] for k in ('finding_id','action','evidence')) and v['action'] in ('accept','reject','escalate'))

def validate_trace(t):
    if not exact(t, TRACE_KEYS) or not count(t['contract_version']) or not isinstance(t['rounds'], list) or not t['rounds']: return 'malformed'
    for r in t['rounds']:
        if not exact(r, ROUND_KEYS) or not isinstance(r['revision_id'], str) or not r['revision_id'] or not valid_artifact(r['artifact']): return 'malformed'
        if not isinstance(r['findings'], list) or not all(valid_finding(x) for x in r['findings']): return 'malformed'
        if not isinstance(r['dispositions'], list) or not all(valid_disposition(x) for x in r['dispositions']): return 'malformed'
        ids = [x['id'] for x in r['findings']]; dids = [x['finding_id'] for x in r['dispositions']]
        if len(ids) != len(set(ids)) or sorted(ids) != sorted(dids): return 'malformed'
        if not finite(r['cost']) or r['cost'] < 0 or not finite(r['time']) or r['time'] < 0: return 'malformed'
    return None

def valid_change(v):
    return exact(v, CHANGE_KEYS) and isinstance(v['incident_id'], str) and bool(v['incident_id']) and isinstance(v['observed_at'], str) and bool(v['observed_at']) and count(v['observed_errors_per_minute'])

def outcome(status, retained, version, rubric=None, candidate=None):
    return {'status': status, 'retained': copy.deepcopy(retained), 'retained_version': version, 'rubric': copy.deepcopy(rubric), 'candidate_rubric': copy.deepcopy(candidate), 'human_decision': UNKNOWN}

def replay(t, changed_input=None):
    error = validate_trace(t)
    if error: return outcome(error, None, None)
    if t['contract_version'] != CONTRACT['version']: return outcome('changed-rubric', None, None)
    cost = time = 0.0; history = set(); retained = version = rubric = final = None
    for i, r in enumerate(t['rounds']):
        if i >= CONTRACT['max_rounds']: return outcome('exceeded-budget', retained, version, rubric)
        cost += r['cost']; time += r['time']
        if cost > CONTRACT['max_cost'] or time > CONTRACT['max_time']: return outcome('exceeded-budget', retained, version, rubric)
        fp = json.dumps(r['artifact'], sort_keys=True, separators=(',', ':'))
        if fp in history: return outcome('cycling', retained, version, rubric)
        history.add(fp)
        by_id = {x['finding_id']: x for x in r['dispositions']}
        for f in r['findings']:
            if f['criterion'] not in RUBRIC: return outcome('invented-criterion', retained, version, rubric)
            if not f['evidence_refs'] or any(x not in VALID_REFS[f['criterion']] for x in f['evidence_refs']): return outcome('missing-evidence', retained, version, rubric)
            if by_id[f['id']]['action'] == 'escalate': return outcome('escalated', retained, version, rubric)
        final = evaluate(r['artifact'])
        if all(final.values()): retained, version, rubric = copy.deepcopy(r['artifact']), r['revision_id'], final
    if changed_input is not None:
        if not valid_change(changed_input): return outcome('malformed', retained, version, rubric, final)
        conflict = (changed_input['incident_id'], changed_input['observed_at'], changed_input['observed_errors_per_minute']) != ('INC-42','14:22 UTC',13)
        if conflict: return outcome('changed-input-conflict', retained, version, rubric, final)
    if final is not None and all(final.values()): return outcome('pass', retained, version, rubric, final)
    if retained is not None: return outcome('regression', retained, version, rubric, final)
    return outcome('needs-review', None, None, None, final)

def finding(i, c, refs, severity, correction): return {'id': i, 'criterion': c, 'evidence_refs': refs, 'severity': severity, 'correction': correction}
def disposition(i, action, evidence): return {'finding_id': i, 'action': action, 'evidence': evidence}
def round_item(v, a, findings=None, dispositions=None, cost=1, elapsed=0.4): return {'revision_id': v, 'artifact': copy.deepcopy(a), 'findings': copy.deepcopy(findings or []), 'dispositions': copy.deepcopy(dispositions or []), 'cost': cost, 'time': elapsed}

GOOD = good_artifact(); BAD = bad_artifact()
FINDINGS = [finding('F1','arithmetic',['baseline_errors_per_minute','peak_errors_per_minute'],'blocking','Replace 40 with 50.'), finding('F2','source_fidelity',['deployment','started_at'],'blocking','Use after, not caused by.'), finding('F3','unsupported_claims',['unknown_fields.full_recovery_time'],'blocking','Remove resolved and retain UNKNOWN.'), finding('F4','unknowns',['unknown_fields.affected_customer_count'],'blocking','Set affected customer count to UNKNOWN.'), finding('F5','source_fidelity',['unknown_fields.cause'],'nonblocking','Name rollback as root cause.')]
DISPOSITIONS = [disposition('F1','accept','The supplied counts calculate to 50 percent.'), disposition('F2','accept','The deployment precedes the incident, but causation is not supplied.'), disposition('F3','accept','Full recovery time is unknown.'), disposition('F4','accept','Affected customer count is unknown.'), disposition('F5','reject','Cause is unknown, so the proposed root cause is unsupported.')]
BASELINE = {'contract_version': 1, 'rounds': [round_item('v1', GOOD, FINDINGS, DISPOSITIONS)]}

def main():
    assert valid_contract() and valid_evidence()
    b = replay(BASELINE)
    assert b['status'] == 'pass' and b['retained_version'] == 'v1' and set(b['rubric']) == set(RUBRIC) and all(b['rubric'].values())
    assert render(b['retained']) == '14:05 UTC: After deployment 7f3a, observed errors increased from 12 to 18 per minute, a 50% increase. The team rolled back at 14:17 UTC; errors were 13 per minute at 14:22 UTC. Cause, affected customer count, and full recovery time: UNKNOWN.'
    changed = {'incident_id': 'INC-42', 'observed_at': '14:22 UTC', 'observed_errors_per_minute': 21}
    c = replay(BASELINE, changed)
    assert c['status'] == 'changed-input-conflict' and c['retained_version'] == 'v1' and c['retained'] == GOOD and all(c['rubric'].values()) and c['human_decision'] == UNKNOWN
    cases = {
        'regression': {'contract_version':1,'rounds':[round_item('v1',GOOD),round_item('v2',BAD)]},
        'invented_criterion': {'contract_version':1,'rounds':[round_item('v1',BAD,[finding('I1','must_use_emojis',['started_at'],'blocking','Add emojis.')],[disposition('I1','reject','Not frozen.')])]},
        'missing_evidence': {'contract_version':1,'rounds':[round_item('v1',BAD,[finding('M1','arithmetic',[],'blocking','Change percentage.')],[disposition('M1','reject','No evidence.')])]},
        'disagreement': {'contract_version':1,'rounds':[round_item('v1',GOOD),round_item('v2',BAD,[finding('D1','unsupported_claims',['unknown_fields.full_recovery_time'],'blocking','Escalate.')],[disposition('D1','escalate','Human decision required.')])]},
        'exceeded_budget': {'contract_version':1,'rounds':[round_item('v1',GOOD,cost=1,elapsed=1.0),round_item('v2',BAD,cost=4,elapsed=2.5)]},
        'cycling': {'contract_version':1,'rounds':[round_item('v1',BAD),round_item('v2',BAD)]},
        'changed_rubric': {'contract_version':2,'rounds':[round_item('v1',GOOD)]},
        'malformed_inputs': {'contract_version':1,'rounds':[dict(round_item('v1',GOOD),cost=True)]}
    }
    expected = {'regression':'regression','invented_criterion':'invented-criterion','missing_evidence':'missing-evidence','disagreement':'escalated','exceeded_budget':'exceeded-budget','cycling':'cycling','changed_rubric':'changed-rubric','malformed_inputs':'malformed'}
    results = {k: replay(v) for k,v in cases.items()}
    assert {k:v['status'] for k,v in results.items()} == expected
    for k in ('regression','disagreement','exceeded_budget'):
        assert results[k]['retained_version'] == 'v1' and results[k]['retained'] == GOOD and all(results[k]['rubric'].values())
    assert results['regression']['candidate_rubric'] and not all(results['regression']['candidate_rubric'].values())
    assert results['cycling']['retained'] is None and results['invented_criterion']['retained'] is None and results['missing_evidence']['retained'] is None
    assert all(v['human_decision'] == UNKNOWN for v in results.values())
    invalid_ref = {'contract_version':1,'rounds':[round_item('v1',GOOD,[finding('X1','source_fidelity',['not_a_valid_reference'],'blocking','Use it.')],[disposition('X1','reject','Invalid reference.')])]}
    assert replay(invalid_ref)['status'] == 'missing-evidence'
    malformed = [[], {'contract_version':1,'rounds':[]}, {'contract_version':1,'rounds':[dict(round_item('v1',GOOD),unexpected='reject')]}, {'contract_version':1,'rounds':[dict(round_item('v1',GOOD, [finding('N1','arithmetic',['baseline_errors_per_minute'],'blocking','Fix it.')], [disposition('N1','accept','Grounded.')]), findings='baseline_errors_per_minute')]}, {'contract_version':1,'rounds':[round_item('v1',dict(GOOD, observed_errors_per_minute=True))]}]
    assert all(replay(x)['status'] == 'malformed' for x in malformed)
    assert replay(BASELINE, ['not','a','record'])['status'] == 'malformed'
    print('PASS baseline rubric: 5/5')
    print('PASS changed input: conflict, retained v1, human decision UNKNOWN')
    print('PASS 8 deterministic failure cases')
    print('PASS 6 malformed shape cases')

if __name__ == '__main__': main()
